/* Competition-led homepage: participation on the left, one persistent season board on the right. */
const climbUI={metric:'volume'};
const climbMetricLabels={volume:'Season volume',efficiency:'Volume / member',participation:'Participation'};
function climbValue(g){return climbUI.metric==='participation'?g.activity:climbUI.metric==='efficiency'?seasonVolume(g)/g.members:seasonVolume(g)}
function climbOrdered(){return worldGuilds().sort((a,b)=>climbValue(b)-climbValue(a)||a.name.localeCompare(b.name))}
function climbFormat(v,gap=false){return climbUI.metric==='participation'?v.toFixed(gap?1:0)+(gap?' pp':'%'):numberCompact(v)}
function climbContext(){const g=state.membership&&guildById(state.membership.id),ordered=climbOrdered(),index=g?ordered.findIndex(x=>x.id===g.id):-1;return {g,ordered,index,gap:index>0?climbValue(ordered[index-1])-climbValue(ordered[index]):0}}
function climbEventStrip(){return `<section class="climb-event-strip" aria-label="Current competition summary"><div class="climb-event-title">${icon('trophy')}<span>GUILD OPEN <b>01</b></span><span class="climb-preview-label">EVENT PREVIEW</span></div><div class="climb-event-detail"><span>Multi-guild season leaderboard</span><i></i><span>Schedule & rewards to be announced</span></div>${link('competition','Competition details '+arrow(),'text-button')}</section>`}
traderHero=function(){const own=state.membership&&guildById(state.membership.id);return `<section class="climb-hero" aria-label="Join your community and compete"><div class="climb-hero-track" aria-hidden="true"><span>03</span><span>02</span><span>01</span></div><div class="climb-hero-copy"><span class="page-eyebrow">XOX GUILDS · COMMUNITY DRIVEN TRADING</span><h1>${own?'YOUR TEAM.<br><span>YOUR NEXT CHALLENGE.</span>':'TRADE TOGETHER.<br><span>CLIMB TOGETHER.</span>'}</h1><p>${own?`Welcome back, ${escapeHtml(state.membership.name||'Trader')}. Track your guild, see your contribution and get ready for the next round.`:'Join your community’s guild.<br>Trade with your people and compete for your place on the leaderboard.'}</p><div class="climb-hero-actions">${own?link('my-guild','Enter my guild '+arrow(),'primary button'):'<a href="#find-community" class="primary button" data-find-community>Find my community '+arrow()+'</a>'}</div><div class="climb-hero-foot">${icon('users')} One community · One guild <span>·</span> No member limit</div></div></section>`};
function climbMetricTabs(){return `<div class="climb-metric-tabs" role="group" aria-label="Leaderboard comparison metric">${[['volume','Volume'],['efficiency','Per member'],['participation','Participation']].map(([id,t])=>`<button data-climb-metric="${id}" aria-pressed="${climbUI.metric===id}" class="${climbUI.metric===id?'selected':''}">${t}</button>`).join('')}</div>`}
function climbRows(){const {ordered,g}=climbContext();return `<ol class="climb-rank-list">${ordered.map((team,i)=>`<li class="${team.id===g?.id?'is-my-guild':''}"><a href="#/${worldLink(team.id)}"><span class="climb-rank-number rank-${i+1}">${String(i+1).padStart(2,'0')}</span><img src="${emblem(team)}" alt=""><span class="climb-rank-team"><strong>${escapeHtml(team.name)}</strong><small>${team.id===g?.id?'YOUR GUILD':team.members.toLocaleString()+' members'}</small></span><span class="climb-rank-value">${climbFormat(climbValue(team))}</span></a></li>`).join('')}</ol>`}
function climbPersonalPosition(){const {g,index,ordered,gap}=climbContext();if(!g)return `<div class="climb-personal-position is-guest"><span class="page-eyebrow">YOUR TEAM COULD BE HERE</span><h3>Find your guild.<br>Join the climb.</h3><p>The leaderboard shows the shared season. Head-to-head battles happen within your guild’s journey.</p><a href="#find-community" data-find-community class="secondary button">Find my community ${arrow()}</a></div>`;if(index<0)return `<div class="climb-personal-position"><span class="page-eyebrow">YOUR GUILD</span><h3>${escapeHtml(g.name)}</h3><p>Your guild is not on this sample leaderboard. Review your team’s competition entry and eligibility.</p>${link('competition/entry','Review team entry '+arrow(),'secondary button')}</div>`;return `<div class="climb-personal-position"><span class="page-eyebrow">YOUR PLACE IN THE CLIMB</span><div class="climb-personal-heading"><img src="${emblem(g)}" alt=""><div><h3>${escapeHtml(g.name)}</h3><small>${climbMetricLabels[climbUI.metric]} · Sample comparison</small></div><strong>#${index+1}</strong></div>${index>0?`<div class="climb-next-position"><span>Gap to #${index} · ${escapeHtml(ordered[index-1].name)}</span><strong>${climbFormat(gap,true)}</strong><small>Difference in ${climbMetricLabels[climbUI.metric].toLowerCase()}</small></div>`:'<div class="climb-next-position"><strong>Setting the pace.</strong><small>Your guild leads this sample comparison.</small></div>'}</div>`}
function climbRail(){return `<aside class="climb-sidebar" aria-label="Persistent season leaderboard"><header><div><span class="page-eyebrow">THE SEASON CLIMB</span><h2>Guild leaderboard</h2></div>${icon('trophy')}</header><div class="climb-rail-status"><span>GUILD OPEN 01</span><span>SAMPLE DATA</span></div><div data-climb-tabs>${climbMetricTabs()}</div><div class="climb-current-metric" data-climb-metric-label>${climbMetricLabels[climbUI.metric]}</div><div data-climb-rows>${climbRows()}</div><div data-climb-personal>${climbPersonalPosition()}</div><footer><span>Comparison preview · Final scoring to be confirmed.</span>${link('rankings','Full leaderboard '+arrow(),'text-button')}</footer></aside>`}
function climbMobileSummary(){const {g,index,ordered,gap}=climbContext();return `<span class="climb-mobile-icon">${icon('chart')}</span><span><small>${g?'YOUR GUILD · SAMPLE RANK':'GUILD OPEN · SAMPLE STANDINGS'}</small><strong>${g?escapeHtml(g.name)+(index>=0?' · #'+(index+1):' · Unranked'):escapeHtml(ordered[0].name)+' · #1'}</strong><em>${g&&index>0?climbFormat(gap,true)+' to #'+index:g&&index===0?'Leading this sample view':'Open the leaderboard'}</em></span>${icon('chevron')}`}
function climbMobileBoard(){return `<details class="climb-mobile-board"><summary data-climb-mobile-summary>${climbMobileSummary()}</summary><div class="climb-mobile-expanded"><div data-climb-tabs>${climbMetricTabs()}</div><div class="climb-current-metric" data-climb-metric-label>${climbMetricLabels[climbUI.metric]}</div><div data-climb-rows>${climbRows()}</div><div data-climb-personal>${climbPersonalPosition()}</div><small class="climb-mobile-note">Sample comparison · Final scoring to be confirmed.</small></div></details>`}
function climbWorldLink(){return `<div class="climb-world-link"><div>${icon('map')}<span><strong>Guild World</strong><small>Explore community homes and the cities in the mist.</small></span></div>${link('world','Explore the world '+arrow(),'text-button')}</div>`}
function climbHome(){climbUI.metric=Object.hasOwn(climbMetricLabels,seasonUI.metric)?seasonUI.metric:'volume';const member=!!state.membership;return `<div class="climb-home">${climbEventStrip()}${climbMobileBoard()}<div class="climb-shell"><div class="climb-main">${traderHero()}<div class="trader-demo-note">${icon('info')} Design preview · Membership and simulated activity stay in this browser. No live orders or rewards.</div>${member?traderMemberBoard():traderCommunityFinder()}${member?'':traderGettingStarted()}${homeBattleFeature()}${member?traderCommunityFinder():''}${traderLeaderStrip()}</div>${climbRail()}</div>${footer()}</div>`}
seasonHome=climbHome;worldHome=climbHome;traderHome=climbHome;
drawNav=function(section){const secondary=[['competition','Competition'],['rankings','Full leaderboard'],['leaders','Guild leaders'],['world','Guild World']];const inMore=secondary.some(([path])=>section===path)||['arena','ranks'].includes(section);$('#guild-navigation').innerHTML=`<div class="guild-subnav compact-guild-nav"><div class="subnav-links"><a href="#/" ${section===''?'class="current" aria-current="page"':''}>Overview</a><a href="#/my-guild" ${section==='my-guild'?'class="current" aria-current="page"':''}>My Guild</a></div><details class="guild-more-nav ${inMore?'is-current':''}"><summary>More ${icon('chevron')}</summary><nav aria-label="More guild pages">${secondary.map(([path,label])=>`<a href="#/${path}" ${section===path?'aria-current="page"':''}>${label}</a>`).join('')}<button data-rank-guide>Guild rank badges</button><button data-action="create">Create a guild</button></nav></details></div>`};

function standaloneGuildWorld(){return `<div class="standalone-guild-world">${breadcrumb(`${link('','Guilds')}<span>/</span>Guild World`)}<div class="standalone-world-heading"><div><span class="page-eyebrow">COMMUNITY EXPLORATION</span><h1>Your community’s place in the world.</h1><p>Four revealed communities. Eight cities in the mist.</p></div>${link('','Back to guild competition '+arrow(),'secondary button')}</div><div id="guild-world-mount">${guildWorld()}</div><p class="standalone-world-note">Community world concept · All districts have equal territory allocation. Standings and battle progression are available in the competition pages.</p>${footer()}</div>`}
const climbBaseRender=renderRoute;
renderRoute=function(scroll=true){const priorPath=routePath,keepFull=worldUI.full&&location.hash.split('?')[0]==='#/world';climbBaseRender(scroll);if(routePath==='world'){if(priorPath!=='world')worldUI.mode='expanded';worldUI.full=keepFull;$('#overview').hidden=true;$('#workspace').hidden=false;$('#workspace').innerHTML=standaloneGuildWorld();document.title='Guild World — XOX Guilds';syncFullscreen()}else if(!routePath)document.title='XOX Guilds — Trade together. Climb together.'};
function updateClimbBoard(){const root=routePath?$('#workspace'):$('#season-home');if(!root)return;root.querySelectorAll('[data-climb-tabs]').forEach(e=>e.innerHTML=climbMetricTabs());root.querySelectorAll('[data-climb-metric-label]').forEach(e=>e.textContent=climbMetricLabels[climbUI.metric]);root.querySelectorAll('[data-climb-rows]').forEach(e=>e.innerHTML=climbRows());root.querySelectorAll('[data-climb-personal]').forEach(e=>e.innerHTML=climbPersonalPosition());root.querySelectorAll('[data-climb-mobile-summary]').forEach(e=>e.innerHTML=climbMobileSummary())}
document.addEventListener('click',e=>{const b=e.target.closest('[data-climb-metric]');if(!b||!Object.hasOwn(climbMetricLabels,b.dataset.climbMetric))return;climbUI.metric=b.dataset.climbMetric;seasonUI.metric=climbUI.metric;updateClimbBoard()});
renderRoute(false);
